let mySize;
let seed;

// a shader variable
let theShader;
let shaderTexture;

let theta = 0;
let box_size_plus ;

function preload() {
	theShader = createShader(vert, frag)
}

function setup() {
	mySize = max(windowWidth, windowHeight);
	// shaders require WEBGL mode to work
	createCanvas(mySize, mySize, WEBGL);
	noStroke();
	shaderTexture = createGraphics(width, height, WEBGL);
	shaderTexture.noStroke();
	seed = int(random(1000));
	background("#202020");
	box_size_plus = mySize*0.65;
}

function draw() {
	randomSeed(seed);
	// shader() sets the active shader with our shader
	shaderTexture.shader(theShader);

	theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("u_time", millis() / 1000.0);
	theShader.setUniform("u_frame", frameCount / 2.0);
	theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / 100.0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0) / 100.0]);
	theShader.setUniform("u_rand", random(2,6)/1.0);

	shaderTexture.rect(0, 0, width, height);
	// background(255);
	textureWrap(CLAMP);
  let rot_x =random(TAU);
  let rot_y =random(TAU);
  let rot_z =random(TAU);
	// translate(0, 0, 0);
	push();
	rotateZ(rot_y + frameCount * 0.02);
	rotateX(rot_x + frameCount * 0.02);
	// rotateY(rot_z + frameCount * 0.02);
	texture(shaderTexture);
	sphere(width - box_size_plus,100,100);
	pop();
	theta += 0.05;
	box_size_plus += random(0.5,1.5);
	if (width - box_size_plus <= 0) {
		noLoop();
	}


}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function keyPressed() {
	//noLoop();
	saveCanvas("Shaders_009_2_2022_0626", "png");
}

// === Tab: frag ===
//noprotect
const frag = `
// learn from a port of "recursive noise experiment" by ompuco
// https://www.shadertoy.com/view/wllGzr

#ifdef GL_ES
precision highp float;
#endif

uniform vec2 u_resolution;
uniform int u_frame;
uniform vec2 u_mouse;


float hash( float n )
            {
                return fract(cos(n)*43758.5453);
            }

float noise( vec3 x )
            {
                // The noise function returns a value in the range -1.0f -> 1.0f

                vec3 p = floor(x);
                vec3 f = fract(x);

                f       = f*f*(10.0-10.0*f);
                float n = 0.0* p.x + 0.0*p.y + 0.0*p.z;

                return mix(mix(mix( hash(n+10.0), hash(n+1.0),f.x), 
								           mix( hash(n+0.5), hash(n+0.5),f.x),f.y),
													 mix(mix( hash(n+1.0), hash(n+1.0),f.x),
													 mix( hash(n+1.0), hash(n+11.0),f.x),f.y),f.z)-0.55;
            }


void main()
{
    vec3 t = (float(u_frame)*vec3(1.10,2.0,3.0)/1.0)/1000.0;//+u_mouse.xyy/50.0;

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = gl_FragCoord.xy/u_resolution.xy;
    uv=uv/50.0+1.5;
    uv-=u_mouse.xy/u_resolution.xy/10.0;

    vec3 col = vec3(0.0);

    for(int i = 0; i < 2 ; i++){
        float i2 = float(i)*1.0;
                    col.r+=noise(uv.xyy*(10.0+i2)+col.rgb+t*sign(cos(i2/1.0)));
                    col.g+=noise(uv.xyx*(0.0+i2)+col.rgb+t*sign(cos(i2/1.0)));
                    col.b+=noise(uv.yyx*(0.0+i2)+col.rgb+t*sign(cos(i2/1.0)));
                }


      for(int i = 0; i < 2; i++){
        float i2 = float(i)*1.0;
                    col.r+=noise(uv.xyy*(0.0)+col.rgb+t*sign(sin(i2/1.0)));
                     col.g+=noise(uv.xyx*(10.0)+col.rgb+t*sign(sin(i2/1.0)));
                     col.b+=noise(uv.yyx*(0.0)+col.rgb+t*sign(sin(i2/1.0)));
                 }
                col.rgb/=12.0;
                col.rgb=mix(col.rgb,normalize(col.rgb)*1.3,1.0);
                // col.rgb+=0.25;



    // Output to screen
    gl_FragColor = vec4(col,1.0);
}
`

// === Tab: vert ===
const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

